alter table accounting.account drop constraint if exists account_type_check;
alter table accounting.account add constraint account_type_check check (type in ('Asset','Equity','Liability'));
create schema if not exists procurement;
grant usage on schema procurement to rbos_app;
create table procurement.supplier (tenant_id uuid not null references core.tenant(id), id uuid not null, name text not null check (length(btrim(name)) between 1 and 120), phone text null check (phone is null or length(phone) <= 30), notes text null check (notes is null or length(notes) <= 300), is_active boolean not null default true, created_at timestamptz not null default now(), primary key (tenant_id, id));
create unique index supplier_name_uq on procurement.supplier (tenant_id, lower(btrim(name)));
create table procurement.purchase_receipt (tenant_id uuid not null references core.tenant(id), id uuid not null, supplier_id uuid not null, location_id uuid not null, receipt_date date not null, supplier_ref text null check (supplier_ref is null or length(supplier_ref) <= 60), total numeric(18,2) not null check (total > 0), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), foreign key (tenant_id, supplier_id) references procurement.supplier(tenant_id, id), foreign key (tenant_id, location_id) references core.stock_location(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
create table procurement.purchase_receipt_line (tenant_id uuid not null, receipt_id uuid not null, product_id uuid not null, quantity numeric(18,3) not null check (quantity > 0), unit_cost numeric(18,4) not null check (unit_cost > 0), primary key (tenant_id, receipt_id, product_id), foreign key (tenant_id, receipt_id) references procurement.purchase_receipt(tenant_id, id), foreign key (tenant_id, product_id) references catalog.product(tenant_id, id));
create table procurement.supplier_payment (tenant_id uuid not null references core.tenant(id), id uuid not null, supplier_id uuid not null, payment_date date not null, amount numeric(18,2) not null check (amount > 0), method text not null check (method in ('Cash','Bank','UPI')), reference text null check (reference is null or length(reference) <= 60), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), foreign key (tenant_id, supplier_id) references procurement.supplier(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
do $$ declare t text; begin foreach t in array array['procurement.supplier','procurement.purchase_receipt','procurement.purchase_receipt_line','procurement.supplier_payment'] loop execute format('alter table %s enable row level security', t); execute format('alter table %s force row level security', t); execute format('create policy tenant_isolation on %s for all to rbos_app using (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id)) with check (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id))', t); end loop; end $$;
grant select, insert on procurement.supplier, procurement.purchase_receipt, procurement.purchase_receipt_line, procurement.supplier_payment to rbos_app;
grant update (name, phone, notes, is_active) on procurement.supplier to rbos_app;
